// route: 0 card button, 1 message, 2 ignore
const body = $json.body || {};
if (body.encrypt) return [{ json: { route: 2, response: {} } }];
if (body.type === 'url_verification') return [{ json: { route: 2, response: { challenge: body.challenge } } }];
const header = body.header || {};
const event = body.event || {};
if (header.event_type === 'card.action.trigger') {
  const value = (event.action && event.action.value) || {};
  return [{
    json: {
      route: 0,
      response: { toast: { type: 'info', content: 'Noted' } },
      action: value.a,
      id: Number(value.id) || 0,
      token: value.t,
      operator: (event.operator && event.operator.open_id) || '',
      chat_id: (event.context && event.context.open_chat_id) || '',
      message_id: (event.context && event.context.open_message_id) || '',
    },
  }];
}
if (header.event_type === 'im.message.receive_v1') {
  const m = event.message || {};
  if (!['p2p', 'group'].includes(m.chat_type)) return [{ json: { route: 2, response: {} } }];
  return [{ json: { route: 1, response: {}, message_id: m.message_id, chat_type: m.chat_type } }];
}
return [{ json: { route: 2, response: {} } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const c = $('Classify').first().json;
const settings = settingsOf('Load settings');
// The owner, or anyone in the team group (everyone there is equal).
const allowed = (settings.lark_open_id && c.operator === settings.lark_open_id) || (settings.lark_chat_id && c.chat_id === settings.lark_chat_id);
if (!allowed) return [];
const row = rowsOf('Load row')[0];
const isOffer = String(c.action || '').startsWith('offer');
const approve = String(c.action || '').endsWith('approve');
const open = isOffer ? ['proposed'] : ['awaiting_approval'];
const base = { reply_to: c.message_id };
if (!row || !c.token || row.approval_token !== c.token) {
  return [{ json: { ...base, valid: false, text: 'That card is out of date.' } }];
}
if (!open.includes(row.status)) {
  return [{ json: { ...base, valid: false, text: `${isOffer ? 'Offer' : 'Post'} #${row.Id} is already ${row.status}.` } }];
}
const label = isOffer ? `offer #${row.Id} "${row.title}" (${row.offer}, launch ${row.launch_date})` : `post #${row.Id} "${row.title}"`;
let agent = '';
if (isOffer && approve) agent = `The team approved ${label}. Plan the posts leading to it now, working backward from what the audience must know and feel.`;
if (isOffer && !approve) agent = `The team rejected ${label}. If you do not know why, ask in one short message. Then propose a different offer for that month.`;
if (!isOffer && !approve) agent = `The team rejected ${label}, planned for ${row.publish_at}. If you do not know why, ask in one short message; then plan something better for that day.`;
return [{
  json: {
    ...base,
    valid: true,
    table: isOffer ? 'offers' : 'posts',
    row_id: row.Id,
    status: approve ? 'approved' : 'rejected',
    event: { type: approve ? 'approved' : 'rejected', post_id: isOffer ? null : row.Id, offer_id: isOffer ? row.Id : null, text: `Manager ${approve ? 'approved' : 'rejected'} ${label}` },
    agent,
    text: approve ? `✅ Approved ${isOffer ? 'offer' : 'post'} #${row.Id}.` : `Rejected ${isOffer ? 'offer' : 'post'} #${row.Id}.`,
  },
}];
